BEGIN TRANSACTION;
CREATE TABLE api_test_config (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id INTEGER NOT NULL UNIQUE REFERENCES run(id) ON DELETE CASCADE,
    model TEXT DEFAULT '',
    reasoning_model TEXT DEFAULT '',
    fc_model TEXT DEFAULT '',
    enable_fc_test INTEGER DEFAULT 0,
    enable_n_test INTEGER DEFAULT 0,
    n_value INTEGER DEFAULT 3
);
CREATE TABLE api_test_result (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
    test_name TEXT NOT NULL,
    category TEXT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('pass', 'fail', 'error')),
    http_code INTEGER,
    response_time_ms INTEGER,
    response_body TEXT,
    error_message TEXT,
    assertion_details TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE compat_test_config (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id INTEGER NOT NULL UNIQUE REFERENCES run(id) ON DELETE CASCADE,
    test_level TEXT DEFAULT 'standard' CHECK(test_level IN ('quick', 'standard', 'comprehensive')),
    framework TEXT DEFAULT 'standard' CHECK(framework IN ('standard', 'sglang', 'vllm')),
    include_extensions INTEGER DEFAULT 0,
    enable_dangerous INTEGER DEFAULT 0,
    timeout_seconds INTEGER DEFAULT 30,
    max_retries INTEGER DEFAULT 3
);
CREATE TABLE run (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    task_id INTEGER NOT NULL REFERENCES task(id) ON DELETE CASCADE,
    concurrency INTEGER NOT NULL DEFAULT 0,
    prompt_multiplier INTEGER NOT NULL DEFAULT 4,
    total_prompts INTEGER DEFAULT 0,
    random_input_len INTEGER NOT NULL DEFAULT 0,
    random_output_len INTEGER NOT NULL DEFAULT 0,
    request_rate REAL NOT NULL DEFAULT 0,
    dataset_name TEXT DEFAULT '',
    limit_val INTEGER DEFAULT 0,
    batch_size INTEGER DEFAULT 0,
    status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'running', 'done', 'failed', 'abort')),
    raw_output TEXT DEFAULT '',
    parsed_result TEXT DEFAULT '{}',
    started_at TIMESTAMP,
    finished_at TIMESTAMP
, test_mode TEXT DEFAULT 'normal' CHECK(test_mode IN ('normal', 'shared_prefix', 'multi_turn')), gsp_num_groups INTEGER DEFAULT 0, gsp_system_prompt_len INTEGER DEFAULT 0, gsp_question_len INTEGER DEFAULT 0, gsp_prompts_per_group INTEGER DEFAULT 0, gsp_range_ratio REAL DEFAULT 0.0, gsp_max_concurrency INTEGER DEFAULT 0, mt_num_clients INTEGER DEFAULT 10, mt_num_rounds INTEGER DEFAULT 5, mt_request_length INTEGER DEFAULT 1024, mt_sub_question_input_length INTEGER DEFAULT 256, mt_output_length INTEGER DEFAULT 256, mt_range_ratio REAL DEFAULT 1.0, mt_max_context_length INTEGER DEFAULT 0, mt_init_interval REAL DEFAULT 0.0, mt_total_requests INTEGER DEFAULT 0, mt_seed INTEGER DEFAULT 0, mt_host_header TEXT DEFAULT '', mt_enable_session_key INTEGER DEFAULT 1, mt_enable_round_barrier INTEGER DEFAULT 0, mt_api_format TEXT DEFAULT 'openai', mt_thinking INTEGER DEFAULT 0);
